  lcm: function (g, r) { var a = lsInt(r, 3, 12), b = lsInt(r, 3, 12); if (a === b) b++; return { q: 'Find the LCM of ' + a + ' and ' + b + '.', a: String(lsLcm(a, b)) }; },
