  fcomp: function (g, r) { var a = lsInt(r, 1, 8), b = lsInt(r, 2, 9), c = lsInt(r, 1, 8), d = lsInt(r, 2, 9); if (a >= b) a = b - 1; if (c >= d) c = d - 1; var l = a * d, rr = c * b; return { q: 'Compare ' + a + '/' + b + ' and ' + c + '/' + d + ' using <, > or =.', a: a + '/' + b + (l < rr ? ' < ' : l > rr ? ' > ' : ' = ') + c + '/' + d + ' (cross products ' + l + ' and ' + rr + ')' }; },
